{
  "name": "MGT508高速瞬态数据采集器",
  "name_en": "MGT508 High-Speed Transient Data Acquisition Unit",
  "manufacturer": "D-TACQ",
  "description": "MGT508是一种高速瞬态数据采集设备，可将实验中的快速电信号捕获到板载存储中，并在采集后将数据回传到主机。它适用于脉冲过程、瞬态波形和其他需要短时高速记录的测量场景。",
  "description_en": "The MGT508 is a high-speed transient data acquisition instrument that captures fast electrical signals into onboard memory and returns the recorded data to a host after acquisition. It is suited to pulsed processes, transient waveform recording, and other experiments requiring short-duration high-speed capture.",
  "tag_hints": [
    "high-speed digitizer",
    "transient recorder",
    "onboard memory capture",
    "waveform acquisition",
    "post-shot data retrieval"
  ],
  "actions": [
    {
      "action_name": "auto-pull",
      "description": "拉取设备已采集的数据。",
      "description_en": "Pull the data captured by the device."
    },
    {
      "action_name": "auto-set_capture_length",
      "description": "设置采集长度（MB）。",
      "description_en": "Define the capture length (MB)."
    }
  ]
}

